  if (!/\.pdf$/i.test(file.name)) { pdfFileStatus.textContent = "Lütfen PDF dosyası seçin."; return; }
  selectedPdfFile = file;
  document.getElementById("btn-clear-pdf-file").classList.remove("hidden");
